const runWithVerify = async (name, dir, prompt, implPhase, verPhase) => {
  let res = await agent(COMMON + '\n\n' + prompt, { label: `implement:${name}`, phase: implPhase, schema: RESULT_SCHEMA })
  let ver = null
  for (let round = 0; round < 2; round++) {
    ver = await agent(COMMON + '\n\n' + VERIFY(name, dir, res), { label: `verify:${name}:${round}`, phase: verPhase, schema: VERIFY_SCHEMA })
    if (ver && ver.passed) break
    log(`${name}: verification round ${round} failed (${ver ? ver.wrong_claims.length : '?'} problems) — fixing`)
    res = await agent(COMMON + `\n\n${round === 0 && name === 'Test H' ? H_FIX_RESUME : ''}TASK: fix ${name} in ${dir} according to the verifier (rerun on maas if results change; regenerate figures, verification.json, SHA256SUMS) and return the complete corrected outputs.\nVerifier:\n${JSON.stringify(ver).slice(0, 9000)}\nPrevious report text:\n${(res && res.report_markdown || '').slice(0, 12000)}`, { label: `fix:${name}:${round}`, phase: implPhase, schema: RESULT_SCHEMA })
  }
  return { res, ver }
}

